"""Render the combined inventory and the separate staged implementation plan."""
from html import escape as e
import json
from pathlib import Path
from site_navigation import project_tabs,experiment_subtabs
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'research/question-catalog'
def read(name):return json.loads((D/name).read_text())
def p(text):return '<p>'+e(str(text))+'</p>'
def clock(t):return f'{int(t)//60}:{int(t)%60:02d}'
def table(number,caption,headers,rows):return '<p class="asset-label table-caption" id="catalog-table-'+str(number)+'">Table '+str(number)+'. '+e(caption)+'</p><div class="table-wrap"><table aria-labelledby="catalog-table-'+str(number)+'"><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def bars(rows):
 maximum=max((n for _,n in rows),default=1) or 1
 return '<ul class="catalog-bars">'+''.join('<li><span>'+e(label)+'</span><span class="bar-track"><span class="bar" style="width:'+str(100*n/maximum)+'%"></span></span><strong>'+str(n)+'</strong></li>' for label,n in rows)+'</ul>'
def hist(rows,bins,key,unit):return bars([(f'{a:g}–{b:g} {unit}',sum(a<=q[key]<(b if i<len(bins)-2 else b+1e-6) for q in rows)) for i,(a,b) in enumerate(zip(bins,bins[1:]))])
def figure(number,title,content,caption,stem=None):return '<figure><h3>'+e(title)+'</h3>'+content+'<figcaption>Figure '+str(number)+'. '+e(caption)+'</figcaption>'+('<p class="downloads">All-question plot: <a href="../research/question-catalog/figures/'+stem+'.png">PNG</a> · <a href="../research/question-catalog/figures/'+stem+'.svg">SVG</a> · <a href="../research/question-catalog/figures/'+stem+'.pdf">PDF</a>.</p>' if stem else '')+'</figure>'
CSS='''.hero h1{overflow-wrap:anywhere}@media(max-width:360px){.hero h1{font-size:2rem}}main{padding-bottom:2rem}.catalog-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.catalog-metrics>div{border:1px solid var(--border);border-radius:10px;padding:1rem}.catalog-metrics dt{font-size:.9rem}.catalog-metrics dd{margin:.4rem 0 0;font-weight:750;font-size:1.8rem}.catalog-filters{display:flex;flex-wrap:wrap;gap:1rem;margin:1.4rem 0}.catalog-filters label{display:grid;gap:.4rem}select{font:inherit;padding:.6rem;max-width:100%}.plot-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem}figure{margin:1rem 0;min-width:0}figcaption,.downloads{font-size:.9rem}.catalog-bars{list-style:none;padding:0}.catalog-bars li{display:grid;grid-template-columns:minmax(100px,1.1fr) minmax(0,2fr) 2.5rem;gap:.6rem;align-items:center;margin:.8rem 0}.bar-track{height:1.25rem;background:#8882}.bar{display:block;height:100%;background:var(--accent)}.table-caption{font-weight:700;line-height:1.6}.table-wrap{max-width:100%;overflow-x:auto}table{width:100%;border-collapse:collapse}caption{padding:1rem 0;text-align:left;font-weight:700}th,td{padding:.8rem;text-align:left;border-bottom:1px solid var(--border);vertical-align:top}.catalog-question{border:1px solid var(--border);border-radius:10px;margin:1rem 0;padding:1rem;min-width:0;scroll-margin-top:8rem}.catalog-question p{overflow-wrap:anywhere}.question{font-size:1.1rem;font-weight:650}.status{display:inline-block;font-weight:700;border:1px solid var(--border);border-radius:999px;padding:.2rem .65rem;font-size:.85rem}.state-schema{display:block;white-space:normal;overflow-wrap:anywhere;padding:1rem;border:1px solid var(--border)}.stage{border-top:1px solid var(--border);padding:1.6rem 0;scroll-margin-top:8rem}.stage li{margin:1rem 0}.stage li p{margin:.35rem 0}.stage-links,.jump-links{display:flex;flex-wrap:wrap;gap:.8rem 1.3rem}.muted{color:var(--muted)}[hidden]{display:none!important}@media(max-width:700px){.catalog-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.plot-grid{grid-template-columns:1fr}.catalog-filters{display:grid;grid-template-columns:1fr}.catalog-bars li{grid-template-columns:minmax(95px,1.1fr) minmax(0,1.6fr) 2rem}}'''
def document(name,title,current,body,js=''):
 nav='<header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header><div class="container collection-nav">'+experiment_subtabs(current)+'</div>'
 html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="'+e(title)+'"><title>'+e(title)+' · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css"><style>'+CSS+'</style></head><body><a class="skip-link" href="#main">Skip to content</a>'+nav+'<main id="main"><div class="container">'+body+'</div></main>'+('<script>'+js+'</script>' if js else '')+'</body></html>'
 (ROOT/'experiments'/name).write_text(html)
def overview():
 s=read('summary.json');qs=read('questions.json')['questions'];a=s['overall'];plotrows=[dict(q,minutes=q['at']/60) for q in qs]
 body='<header class="hero"><span class="eyebrow">Combined question inventory</span><h1>All questions and aggregate statistics</h1><p class="lede">'+str(a['questions'])+' distinct questions across '+str(a['conversations'])+' conversations. The count includes all four retained studies, with alternative phrasings and later repeats grouped under their question.</p><p>The previously reported 83 covered the two latest batches. The first pilot adds seven questions and the earlier expansion adds fifteen. The complete inventory has '+str(a['questions'])+' questions and '+str(a['alternative_records'])+' alternatives or later repeats, stored as '+str(a['accepted_text_records'])+' accepted text records.</p></header>'
 body+='<section class="section" id="statistics"><h2>Question counts and insertion times</h2><p>Filters update the totals, charts and question list below. Each distinct question contributes once. “Near 5–10 minutes” means an actual saved insertion position from 4:30 through 10:30 after the recording starts.</p><div class="catalog-filters"><label>Conversation source<select id="dataset-filter"><option value="all">All sources</option><option value="AMI">AMI meetings</option><option value="Earnings calls">Earnings calls</option></select></label><label>Study<select id="batch-filter"><option value="all">All four studies</option>'+''.join('<option value="'+b['id']+'">'+e(b['label'])+'</option>' for b in s['batches'])+'</select></label></div><p id="filter-state" aria-live="polite">All sources · all four studies</p><dl class="catalog-metrics">'
 tiles=[('stat-questions','Distinct questions',str(a['questions'])),('stat-meetings','Conversations',str(a['conversations'])),('stat-mean-time','Mean insertion time',f"{a['mean_minutes']:.2f} min"),('stat-mean-percent','Mean meeting progress',f"{a['mean_percent']:.2f}%"),('stat-early','Near 5–10 minutes',str(a['early_questions'])),('stat-audio','Questions with audio',str(a['audio_questions']))]
 body+=''.join('<div><dt>'+e(label)+'</dt><dd id="'+id+'">'+e(value)+'</dd></div>' for id,label,value in tiles)+'</dl><div class="plot-grid">'
 body+=figure(1,'Elapsed time before insertion','<div id="elapsed-chart">'+hist(plotrows,s['elapsed_bins'],'minutes','min')+'</div>','Count per time interval, using the source recording clock.','elapsed-time')
 body+=figure(2,'Fraction of the conversation elapsed','<div id="percent-chart">'+hist(plotrows,s['percentage_bins'],'percent','%')+'</div>','Insertion time divided by the full conversation duration. This is not the age of the supporting evidence.','meeting-progress')
 body+=figure(3,'Questions by conversation source','<div id="dataset-chart">'+bars([(r['dataset'],r['questions']) for r in s['datasets']])+'</div>','Retained questions from AMI and from the two earnings calls.')
 body+=figure(4,'Questions by study','<div id="batch-chart">'+bars([(b['label'],b['questions']) for b in s['batches']])+'</div>','Each question is assigned to its retained study; diagnostic copies in later reports are excluded.','study-counts')+'</div><p>Means use the exact saved times, not bin centers. The available insertion points were chosen for development; these plots are not an estimate of how often real meeting participants ask questions.</p><details><summary>Timing and counting rules</summary>'+p(s['timing_definition'])+p(s['count_definition'])+'<p>Two original outreach questions use the later planned replay point, 26:18.92, instead of their 24:49.99 transcript cutoff. AMI durations come from official meeting metadata; call fractions use the complete Earnings21 recording durations. The current exports add the spoken cue where missing and use the recorded audio pause position. Original question-generation texts and transcript cutoffs remain preserved.</p><p><a href="../research/question-catalog/overlap-review.json">Cross-study duplicate review</a> · <a href="../research/question-catalog/questions.csv">Exact question/timing CSV</a> · <a href="../research/question-catalog/questions.json">Complete question index</a></p></details></section>'
 body+='<section class="section" id="inventory"><h2>How the inventory grew</h2>'
 body+=table(1,'Complete inventory by study. This fixed table includes all sources; the filters above control the charts and browsing list. Alternatives or later repeats are saved but do not increase the distinct-question total. The same six conversations appear in both the expansion and early/audio pilot, so conversation counts overlap between rows.',['Study','Distinct questions','Alternatives / later repeats','Conversations','Questions with audio','Mean insertion'],[['<a href="'+b['url']+'">'+e(b['label'])+'</a>',b['questions'],b['alternative_records'],b['conversations'],b['audio_questions'],f"{b['mean_minutes']:.2f} min / {b['mean_percent']:.2f}%"] for b in s['batches']])+'<p>The 26 conversations comprise 24 AMI meetings and two earnings calls. One of the twenty additional AMI meetings produced no retained question and is not included in the conversation total. Questions with different required facts remain separate even when their topics overlap; the original audience alone, for example, differs from comparing original and revised audiences.</p><details><summary>Exact counts and timing by conversation</summary>'
 body+=table(2,'All retained conversations. Mean times count one representative per distinct question.',['Conversation','Source','Questions','Mean time','Mean progress','With audio'],[[r['meeting'],r['dataset'],r['questions'],f"{r['mean_minutes']:.2f} min",f"{r['mean_percent']:.2f}%",r['audio_questions']] for r in s['meetings']])
 body+=figure(5,'Question counts by conversation',bars([(r['meeting'],r['questions']) for r in sorted(s['meetings'],key=lambda r:(-r['questions'],r['meeting']))]),'Complete inventory; this figure stays fixed when the filters above change.','conversation-counts')+'</details></section>'
 body+='<section class="section" id="coverage"><h2>Speech coverage and remaining checks</h2><p><strong>'+str(a['audio_questions'])+' distinct questions have synthesized audio.</strong> The <a href="question-audio.html">complete audio library</a> includes 92 new recordings and retains the original thirteen. The three original questions also have other TTS-model comparisons; these do not count as new questions. Audio covers '+str(s['audio_requester_voices'])+' requester voices across '+str(a['conversations'])+' conversations.</p><p><strong>'+str(a['spoken_cue_questions'])+' of '+str(a['questions'])+' primary texts include the spoken “Assistant,” cue.</strong> All current alternatives also receive the cue. Original generation and reader records remain historical evidence. Every question has a representative recording with the wake word; the library labels any retained alternative used by an older recording.</p><p>Voice conditioning uses earlier same-speaker speech where available. A few sparse early speakers use separately authorized enrollment from later speech, explicitly labeled and excluded from duplex-model history. The frozen twenty-question subset uses earlier conditioning speech throughout.</p><p>Codex wrote or reviewed the retained questions and references. Difficulty has not been uniformly validated. Model agreement, multiple citations and recent-context errors do not establish multi-hop reasoning. Human naturalness/voice ratings, verified fact checklists and the four system conditions remain on the <a href="question-plan.html">four-stage project TODO</a>.</p></section>'
 body+='<section class="section" id="browse"><h2>Browse the combined question index</h2><p id="browse-count">'+str(len(qs))+' distinct questions shown</p><details id="question-browser"><summary>Open the filtered question list</summary>'
 for q in qs:
  body+='<article class="catalog-question" data-batch="'+q['batch']+'" data-dataset="'+e(q['dataset'])+'"><p class="question">'+e(q['question'])+'</p>'+p(q['meeting']+' · requester '+q['requester']+' · '+clock(q['at'])+' · '+f"{q['percent']:.1f}% elapsed")+'<p><a href="'+e(q['report_url'])+'">'+e(q['batch_label'])+' · source review</a>'+(' · <a href="'+q['audio_url']+'">Listen to its audio clips</a>' if q['has_audio'] else '')+'</p></article>'
 body+='</details></section><footer class="section"><p><a href="../research/question-catalog/summary.json">Aggregate data</a> · <a href="../research/question-catalog/manifest.json">File hashes</a> · <a href="question-plan.html">TODO and implementation plan</a>.</p><p>Inventory analysis and page generation use 0 GPUs. Audio-generation resources are reported with the speech study.</p></footer>'
 packed=json.dumps(dict(questions=[dict(batch=q['batch'],dataset=q['dataset'],meeting=q['meeting'],minutes=q['at']/60,percent=q['percent'],has_audio=q['has_audio']) for q in qs],batches=[dict(id=b['id'],label=b['label']) for b in s['batches']],time_bins=s['elapsed_bins'],percent_bins=s['percentage_bins']),ensure_ascii=False).replace('<','\\u003c')
 body+='<script id="catalog-data" type="application/json">'+packed+'</script>'
 js='''const data=JSON.parse(document.getElementById('catalog-data').textContent),dataset=document.getElementById('dataset-filter'),batch=document.getElementById('batch-filter');const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function bars(rows){const max=Math.max(1,...rows.map(r=>r[1]));return '<ul class="catalog-bars">'+rows.map(([name,n])=>'<li><span>'+esc(name)+'</span><span class="bar-track"><span class="bar" style="width:'+(100*n/max)+'%"></span></span><strong>'+n+'</strong></li>').join('')+'</ul>';}function hist(rows,bins,key,unit){return bars(bins.slice(0,-1).map((a,i)=>[a+'–'+bins[i+1]+' '+unit,rows.filter(q=>q[key]>=a&&(q[key]<bins[i+1]||(i===bins.length-2&&q[key]===bins[i+1]))).length]));}function update(){const rows=data.questions.filter(q=>(dataset.value==='all'||q.dataset===dataset.value)&&(batch.value==='all'||q.batch===batch.value)),n=rows.length;const put=(id,t)=>document.getElementById(id).textContent=t;put('stat-questions',n);put('stat-meetings',new Set(rows.map(q=>q.meeting)).size);put('stat-mean-time',n?(rows.reduce((s,q)=>s+q.minutes,0)/n).toFixed(2)+' min':'—');put('stat-mean-percent',n?(rows.reduce((s,q)=>s+q.percent,0)/n).toFixed(2)+'%':'—');put('stat-early',rows.filter(q=>q.minutes>=4.5&&q.minutes<=10.5).length);put('stat-audio',rows.filter(q=>q.has_audio).length);document.getElementById('elapsed-chart').innerHTML=hist(rows,data.time_bins,'minutes','min');document.getElementById('percent-chart').innerHTML=hist(rows,data.percent_bins,'percent','%');document.getElementById('dataset-chart').innerHTML=bars(['AMI','Earnings calls'].map(d=>[d,rows.filter(q=>q.dataset===d).length]));document.getElementById('batch-chart').innerHTML=bars(data.batches.map(b=>[b.label,rows.filter(q=>q.batch===b.id).length]));put('filter-state',dataset.options[dataset.selectedIndex].text+' · '+batch.options[batch.selectedIndex].text);put('browse-count',n+' distinct questions shown');for(const c of document.querySelectorAll('.catalog-question'))c.hidden=!((dataset.value==='all'||c.dataset.dataset===dataset.value)&&(batch.value==='all'||c.dataset.batch===batch.value));}dataset.addEventListener('change',update);batch.addEventListener('change',update);update();'''
 document('question-overview.html','All questions and aggregate statistics','ami-overview',body,js)
def plan():
 r=read('plan.json');labels={'complete':'Done','partial':'Partly complete','pending':'To do','planned':'Later stage'}
 body='<header class="hero"><span class="eyebrow">Implementation roadmap</span><h1>TODO and staged implementation plan</h1><p class="lede">'+e(r['scope'])+'</p>'+p(r['current_state'])+'</header><section class="section" id="next"><h2>Next work</h2><ol>'+''.join('<li>'+e(t)+'</li>' for t in r['next'])+'</ol><p>The list below tracks the broader implementation. Completed pilot checklists are evidence for individual steps; they do not mean the whole project is finished.</p></section><nav class="jump-links" aria-label="Implementation stages">'+''.join('<a href="#'+s['id']+'">'+e(s['title'])+'</a>' for s in r['stages'])+'</nav><section class="section" id="choices"><h2>Choices already made</h2><ul>'+''.join('<li>'+e(t)+'</li>' for t in r['choices'])+'</ul></section>'
 body+=table(1,'Implementation stages and current status. “Partly complete” means working pilot evidence exists while listed tasks remain unfinished; no stage status implies a general model capability.',['Stage','Status','What it establishes'],[[f'<a href="#{s["id"]}">'+e(s['title'])+'</a>',labels[s['status']],e(s['goal'])] for s in r['stages']])
 for s in r['stages']:
  body+='<section class="stage" id="'+s['id']+'"><h2>'+e(s['title'])+'</h2><span class="status">'+labels[s['status']]+'</span>'+p(s['goal'])
  if s['id']=='history':body+='<p><strong>Meeting-state record</strong></p><code class="state-schema">'+e(r['meeting_state_schema'])+'</code>'
  if s['id']=='comparison':body+=table(2,'Four matched system conditions for the original three audio questions. These are planned conditions, not completed AMI results.',['Condition','Available history','What it establishes'],[[e(c['condition']),e(c['history']),e(c['establishes'])] for c in r['conditions']])+'<p><strong>The preparation process must not see the future question.</strong> Count its full pre-request compute, including preparation that never becomes useful. Qualify bounded history retention before extending to 18–35 minutes.</p>'
  if s['id']=='actions':body+='<p><strong>Action choices:</strong> '+e(' · '.join(r['actions']))+'</p>'
  body+='<ul>'
  for t in s['tasks']:body+='<li data-status="'+t['status']+'"><strong>'+labels[t['status']]+' · '+e(t['text'])+'</strong>'+(p(t['evidence']) if t.get('evidence') else '')+('<p><a href="'+e(t['url'])+'">Related evidence or proposal</a></p>' if t.get('url') else '')+'</li>'
  body+='</ul></section>'
 body+='<footer class="section"><h2>Keep the plan synchronized</h2>'+p(r['update_rule'])+'<p><a href="../research/question-catalog/plan.json">Saved stage and task records</a> · <a href="question-overview.html">All question statistics</a> · <a href="../research/question-pilot/progress.json">Earlier completed pilot checklist</a>.</p><p>'+e(r.get('resource_note','Page generation uses 0 GPUs.'))+'</p></footer>'
 document('question-plan.html','TODO and staged implementation plan','ami-plan',body)
def main():overview();plan();print('Rendered aggregate overview and',len(read('plan.json')['stages']),'project stages.')
if __name__=='__main__':main()
